.version 7.8
.target sm_89
.address_size 64
.visible .entry layernorm_rowwise(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .s32 row_size,
    .param .f32 eps
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<12>;
    .reg .b64 %rd<32>;
    .reg .f32 %f<24>;
    .reg .f64 %fd<48>;
    .shared .align 8 .f64 s_sum[256];
    .shared .align 8 .f64 s_ssq[256];
    .shared .align 8 .f64 s_mean[1];
    .shared .align 8 .f64 s_rstd[1];
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.s32 %r1, [row_size];
    ld.param.f32 %f1, [eps];
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;
    // base byte offset of this row: blockIdx.x * row_size * 4
    mul.lo.s32 %r4, %r3, %r1;
    cvt.u64.u32 %rd5, %r4;
    shl.b64 %rd5, %rd5, 2;
    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;
    // vector path is valid when each row is 16-byte aligned: row_size % 4 == 0
    shr.u32 %r6, %r1, 2;
    and.b32 %r7, %r1, 3;
    setp.eq.s32 %p2, %r7, 0;
    @%p2 bra VEC1;
    // scalar fallback pass 1
    mov.u32 %r5, %r2;
LOOP1:
    setp.lt.s32 %p1, %r5, %r1;
    @!%p1 bra LOOP1_END;
    cvt.u64.u32 %rd6, %r5;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd7, %rd1, %rd5;
    add.s64 %rd7, %rd7, %rd6;
    ld.global.f32 %f2, [%rd7];
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r5, %r5, 256;
    bra LOOP1;
LOOP1_END:
    bra PASS1_DONE;
    // pass 1: vectorized float4 accumulate sum and sum of squares in f64
VEC1:
    mov.u32 %r5, %r2;
VLOOP1:
    setp.lt.s32 %p1, %r5, %r6;
    @!%p1 bra VLOOP1_END;
    cvt.u64.u32 %rd6, %r5;
    shl.b64 %rd6, %rd6, 4;
    add.s64 %rd7, %rd1, %rd5;
    add.s64 %rd7, %rd7, %rd6;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd7];
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f3;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f4;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f5;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r5, %r5, 256;
    bra VLOOP1;
VLOOP1_END:
    // up to three tail elements are folded into thread 0 for general row sizes
    setp.eq.s32 %p1, %r7, 0;
    @%p1 bra PASS1_DONE;
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra PASS1_DONE;
    shl.b32 %r8, %r6, 2;
TAIL1:
    setp.lt.s32 %p1, %r8, %r1;
    @!%p1 bra PASS1_DONE;
    cvt.u64.u32 %rd18, %r8;
    shl.b64 %rd18, %rd18, 2;
    add.s64 %rd19, %rd1, %rd5;
    add.s64 %rd19, %rd19, %rd18;
    ld.global.f32 %f2, [%rd19];
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r8, %r8, 1;
    bra TAIL1;
PASS1_DONE:
    // store per-thread partials to shared memory
    cvt.u64.u32 %rd8, %r2;
    shl.b64 %rd8, %rd8, 3;
    mov.u64 %rd9, s_sum;
    add.s64 %rd9, %rd9, %rd8;
    st.shared.f64 [%rd9], %fd1;
    mov.u64 %rd10, s_ssq;
    add.s64 %rd10, %rd10, %rd8;
    st.shared.f64 [%rd10], %fd2;
    bar.sync 0;
    // tree reduction over 256 partials
    mov.u32 %r6, 128;
RED_LOOP:
    setp.lt.u32 %p1, %r2, %r6;
    @!%p1 bra RED_SKIP;
    mul.wide.u32 %rd16, %r6, 8;
    mov.u64 %rd9, s_sum;
    add.s64 %rd9, %rd9, %rd8;
    add.s64 %rd17, %rd9, %rd16;
    ld.shared.f64 %fd5, [%rd9];
    ld.shared.f64 %fd6, [%rd17];
    add.f64 %fd5, %fd5, %fd6;
    st.shared.f64 [%rd9], %fd5;
    mov.u64 %rd10, s_ssq;
    add.s64 %rd10, %rd10, %rd8;
    add.s64 %rd17, %rd10, %rd16;
    ld.shared.f64 %fd7, [%rd10];
    ld.shared.f64 %fd8, [%rd17];
    add.f64 %fd7, %fd7, %fd8;
    st.shared.f64 [%rd10], %fd7;
RED_SKIP:
    bar.sync 0;
    shr.u32 %r6, %r6, 1;
    setp.gt.u32 %p1, %r6, 0;
    @%p1 bra RED_LOOP;
    // thread 0 computes mean and rstd
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra STATS_END;
    mov.u64 %rd9, s_sum;
    ld.shared.f64 %fd5, [%rd9];
    mov.u64 %rd10, s_ssq;
    ld.shared.f64 %fd6, [%rd10];
    cvt.rn.f64.s32 %fd7, %r1;
    div.rn.f64 %fd8, %fd5, %fd7;
    div.rn.f64 %fd9, %fd6, %fd7;
    mul.f64 %fd10, %fd8, %fd8;
    sub.f64 %fd11, %fd9, %fd10;
    cvt.f64.f32 %fd12, %f1;
    add.f64 %fd11, %fd11, %fd12;
    sqrt.rn.f64 %fd13, %fd11;
    mov.f64 %fd14, 0d3FF0000000000000;
    div.rn.f64 %fd15, %fd14, %fd13;
    mov.u64 %rd11, s_mean;
    st.shared.f64 [%rd11], %fd8;
    mov.u64 %rd12, s_rstd;
    st.shared.f64 [%rd12], %fd15;
STATS_END:
    bar.sync 0;
    mov.u64 %rd11, s_mean;
    ld.shared.f64 %fd16, [%rd11];
    mov.u64 %rd12, s_rstd;
    ld.shared.f64 %fd17, [%rd12];
    cvt.rn.f32.f64 %f3, %fd16;
    cvt.rn.f32.f64 %f4, %fd17;
    @%p2 bra VEC2;
    // scalar fallback pass 2
    mov.u32 %r5, %r2;
LOOP2:
    setp.lt.s32 %p1, %r5, %r1;
    @!%p1 bra LOOP2_END;
    cvt.u64.u32 %rd6, %r5;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd7, %rd1, %rd5;
    add.s64 %rd7, %rd7, %rd6;
    ld.global.f32 %f5, [%rd7];
    add.s64 %rd13, %rd3, %rd6;
    ld.global.f32 %f6, [%rd13];
    add.s64 %rd14, %rd4, %rd6;
    ld.global.f32 %f7, [%rd14];
    sub.f32 %f8, %f5, %f3;
    mul.f32 %f8, %f8, %f4;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd15, %rd2, %rd5;
    add.s64 %rd15, %rd15, %rd6;
    st.global.f32 [%rd15], %f9;
    add.s32 %r5, %r5, 256;
    bra LOOP2;
LOOP2_END:
    bra KERNEL_END;
    // pass 2: vectorized normalize, affine transform, and store
VEC2:
    shr.u32 %r6, %r1, 2;
    mov.u32 %r5, %r2;
VLOOP2:
    setp.lt.s32 %p1, %r5, %r6;
    @!%p1 bra VLOOP2_END;
    cvt.u64.u32 %rd6, %r5;
    shl.b64 %rd6, %rd6, 4;
    add.s64 %rd7, %rd1, %rd5;
    add.s64 %rd7, %rd7, %rd6;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd7];
    add.s64 %rd13, %rd3, %rd6;
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd13];
    add.s64 %rd14, %rd4, %rd6;
    ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%rd14];
    sub.f32 %f17, %f5, %f3;
    mul.f32 %f17, %f17, %f4;
    fma.rn.f32 %f17, %f17, %f9, %f13;
    sub.f32 %f18, %f6, %f3;
    mul.f32 %f18, %f18, %f4;
    fma.rn.f32 %f18, %f18, %f10, %f14;
    sub.f32 %f19, %f7, %f3;
    mul.f32 %f19, %f19, %f4;
    fma.rn.f32 %f19, %f19, %f11, %f15;
    sub.f32 %f20, %f8, %f3;
    mul.f32 %f20, %f20, %f4;
    fma.rn.f32 %f20, %f20, %f12, %f16;
    add.s64 %rd15, %rd2, %rd5;
    add.s64 %rd15, %rd15, %rd6;
