    setp.lt.s32 %p1, %r8, %r1;
    @!%p1 bra KERNEL_END;
    cvt.u64.u32 %rd18, %r8;
    shl.b64 %rd18, %rd18, 2;
    add.s64 %rd19, %rd1, %rd5;
    add.s64 %rd19, %rd19, %rd18;
    ld.global.f32 %f5, [%rd19];
    add.s64 %rd20, %rd3, %rd18;
    ld.global.f32 %f6, [%rd20];
    add.s64 %rd21, %rd4, %rd18;
    ld.global.f32 %f7, [%rd21];
    sub.f32 %f8, %f5, %f3;
    mul.f32 %f8, %f8, %f4;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd22, %rd2, %rd5;
    add.s64 %rd22, %rd22, %rd18;
    st.global.f32 [%rd22], %f9;
